-- Saved month presentation shared by the editor, A4 export and phone wallpaper.
-- Apply through Supabase migrations before deploying the corresponding editor.
begin;
create table public.prayer_timetable_months (
 month date primary key check(extract(day from month)=1),
 design jsonb not null default '{}'::jsonb check(jsonb_typeof(design)='object' and octet_length(design::text)<=150000),
 published boolean not null default false,
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now()
);
alter table public.prayer_timetable_months enable row level security;
revoke all on public.prayer_timetable_months from public,anon,authenticated;
grant select on public.prayer_timetable_months to anon,authenticated;
grant all on public.prayer_timetable_months to service_role;
create policy timetable_month_published on public.prayer_timetable_months for select to anon,authenticated using(published);
create policy timetable_month_editor_read on public.prayer_timetable_months for select to authenticated using(private.has_permission('prayer_times'));

create function private.save_prayer_timetable_month(p_month date,p_design jsonb,p_published boolean,p_expected_revision integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare old_row public.prayer_timetable_months; saved public.prayer_timetable_months;
begin
 if auth.uid() is null or not private.has_permission('prayer_times') then raise exception 'Prayer timetable permission required'; end if;
 if p_month is null or extract(day from p_month)<>1 then raise exception 'Use the first date of the timetable month'; end if;
 if p_design is null or jsonb_typeof(p_design)<>'object' or octet_length(p_design::text)>150000 then raise exception 'Provide a valid bounded timetable design'; end if;
 if p_published is null or p_expected_revision is null or p_expected_revision<0 then raise exception 'Publication choice and revision required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_month::text,913));
 select * into old_row from public.prayer_timetable_months where month=p_month for update;
 if coalesce(old_row.revision,0)<>p_expected_revision then raise exception 'This month design changed in another editor. Reload before saving'; end if;
 insert into public.prayer_timetable_months(month,design,published,revision)
 values(p_month,p_design,p_published,p_expected_revision+1)
 on conflict(month) do update set design=excluded.design,published=excluded.published,revision=excluded.revision,updated_at=now()
 returning * into saved;
 return to_jsonb(saved);
end; $$;
revoke all on function private.save_prayer_timetable_month(date,jsonb,boolean,integer) from public,anon,authenticated;
grant execute on function private.save_prayer_timetable_month(date,jsonb,boolean,integer) to authenticated;
-- Public RPC forwards to the checked private write path; direct table writes remain revoked.
create function public.save_prayer_timetable_month(p_month date,p_design jsonb,p_published boolean,p_expected_revision integer)
returns jsonb language sql security invoker set search_path='' as $$
 select private.save_prayer_timetable_month(p_month,p_design,p_published,p_expected_revision)
$$;
revoke all on function public.save_prayer_timetable_month(date,jsonb,boolean,integer) from public,anon,authenticated;
grant execute on function public.save_prayer_timetable_month(date,jsonb,boolean,integer) to authenticated;

